"""自动生成：DeepSeek 小海豚托盘图标（勿手改，改 make_icon.py 后重跑）"""
import base64
import io

from PIL import Image

RUNNING = ""

STOPPED = ""

def load(running):
    """返回托盘图标 Image（running=True 绿点 / False 红点）"""
    raw = base64.b64decode(RUNNING if running else STOPPED)
    return Image.open(io.BytesIO(raw)).convert("RGBA")
